import 'dart:convert';import 'package:flutter_test/flutter_test.dart';import 'package:flutter_secure_storage/flutter_secure_storage.dart';import 'package:http/http.dart' as http;import 'package:http/testing.dart';import 'package:mobile_shared/mobile_api.dart';import 'package:mobile_shared/mobile_v1.generated.dart';import 'package:mobile_shared/settlement_beneficiary_mutation.dart';import 'mobile_session_race_test.dart' as fixture;
String id(int n)=>'00000000-0000-4000-8000-${n.toString().padLeft(12,'0')}';
const destination='4zMMC9srt5Ri5X14GAgXhaHii3GnPAEERYPJgZJDncDU';
Map<String,dynamic> challenge()=>{'version':1,'domain':'bitpos.driver-settlement.v1','tenantId':id(88),'accountId':fixture.session('1')['accountId'],'deviceId':id(99),'enrollmentId':id(90),'challengeId':id(91),'nonce':'a'*64,'destinationOwner':destination,'genesisHash':'EtWTRABZaYq6iMfeYKouRu166VU2xqa1wcaWoxPkrZBG','issuedAt':'2026-10-19T01:00:00Z','expiresAt':'2026-10-19T01:10:00Z'};
Map<String,dynamic> receipt()=>{'kind':'BENEFICIARY_PENDING','beneficiaryId':id(90),'state':'PENDING','version':'1','challenge':challenge(),'outwardReady':false};
EnrollSettlementBeneficiary command(int n)=>EnrollSettlementBeneficiary(SettlementEnrollCommand(idempotencyKey:id(n),expectedVersion:'0',merchantId:id(88),provider:'solana-devnet',publicKey:destination));
void main(){TestWidgetsFlutterBinding.ensureInitialized();setUp(()=>FlutterSecureStorage.setMockInitialValues({'bitpos.mobileSession':jsonEncode(fixture.session('1')),'bitpos.deviceId':id(99)}));
 test('ambiguous enrollment survives API restart and blocks replacement before exact replay',()async{
  var lost=true;final bodies=<String>[];MobileApi make()=>MobileApi(base:Uri.parse('http://127.0.0.1/api/mobile/v1/'),fixture:true,client:MockClient((request)async{bodies.add(request.body);if(lost){lost=false;throw http.ClientException('Synthetic committed response loss');}return http.Response(jsonEncode(receipt()),200);}));
  final original=make();await original.restore();await expectLater(original.submitSettlementBeneficiary(command(92)),throwsA(isA<http.ClientException>()));original.close();final recovered=make();addTearDown(recovered.close);await recovered.restore();final saved=await recovered.pendingSettlementBeneficiary();expect(saved,isA<EnrollSettlementBeneficiary>());
  await expectLater(recovered.submitSettlementBeneficiary(command(93)),throwsA(isA<MobileApiException>().having((e)=>e.code,'code','PENDING_SETTLEMENT_RECOVERY_REQUIRED')));expect(bodies.length,1);final result=await recovered.submitSettlementBeneficiary(saved!);expect(result,isA<SettlementBeneficiaryPendingReceipt>());expect(bodies[1],bodies[0]);expect(await recovered.pendingSettlementBeneficiary(),isNull);
 });
 for(final field in ['accountId','tenantId','destinationOwner','enrollmentId','deviceId']){
  test('mismatched enrollment $field cannot retire original journal',()async{
   final value=receipt();(value['challenge'] as Map<String,dynamic>)[field]=field=='destinationOwner'?'11111111111111111111111111111111':id(98);
   final api=MobileApi(base:Uri.parse('http://127.0.0.1/api/mobile/v1/'),fixture:true,client:MockClient((_)async=>http.Response(jsonEncode(value),200)));addTearDown(api.close);await api.restore();await expectLater(api.submitSettlementBeneficiary(command(92)),throwsA(isA<FormatException>()));expect((await api.pendingSettlementBeneficiary())?.body['idempotencyKey'],id(92));
  });
 }
 test('canonical message binds every challenge field in protocol order without transaction authorization',(){final c=SettlementOwnershipChallenge.fromJson(challenge());final message=settlementOwnershipMessage(c);expect(jsonDecode(message),['BitPOS/SolanaDevnet/PayoutBeneficiaryOwnership/v1',1,c.domain,c.genesisHash,c.tenantId,c.accountId,c.deviceId,c.enrollmentId,c.challengeId,c.nonce,c.destinationOwner,c.issuedAt,c.expiresAt]);final other=SettlementOwnershipChallenge.fromJson({...challenge(),'nonce':'b'*64});expect(settlementOwnershipMessage(other),isNot(message));});
 test('fresh merchant rejection allows corrected enrollment; ambiguous replay rejection remains recoverable',()async{
  var calls=0;final api=MobileApi(base:Uri.parse('http://127.0.0.1/api/mobile/v1/'),fixture:true,client:MockClient((request)async{calls++;if(calls==1)return http.Response('{"error":{"code":"RESOURCE_NOT_FOUND"}}',404);if(calls==3)throw http.ClientException('Synthetic unknown commit');if(calls==4)return http.Response('{"error":{"code":"RESOURCE_NOT_FOUND"}}',404);return http.Response(jsonEncode(receipt()),200);}));addTearDown(api.close);await api.restore();
  await expectLater(api.submitSettlementBeneficiary(command(92)),throwsA(isA<MobileApiException>()));expect(await api.pendingSettlementBeneficiary(),isNull);await api.submitSettlementBeneficiary(command(93));expect(await api.pendingSettlementBeneficiary(),isNull);
  await expectLater(api.submitSettlementBeneficiary(command(94)),throwsA(isA<http.ClientException>()));await expectLater(api.submitSettlementBeneficiary(command(94)),throwsA(isA<MobileApiException>()));expect((await api.pendingSettlementBeneficiary())?.body['idempotencyKey'],id(94));
 });
  test('lost verification reauthentication retires original authority without replay or logout',()async{
   final storage=const FlutterSecureStorage(),mut=VerifySettlementBeneficiary(id(90),SettlementBeneficiaryVerifyCommand(idempotencyKey:id(95),expectedVersion:'1',signature:'1'*88));var verifies=0,retirements=0;
   final original=MobileApi(base:Uri.parse('http://127.0.0.1/api/mobile/v1/'),fixture:true,client:MockClient((request)async{verifies++;throw http.ClientException('Synthetic verification response loss');}));await original.restore();await expectLater(original.submitSettlementBeneficiary(mut),throwsA(isA<http.ClientException>()));original.close();
   final replacement={...fixture.session('1'),'sessionId':id(97)};await storage.write(key:'bitpos.mobileSession',value:jsonEncode(replacement));
   final recovered=MobileApi(base:Uri.parse('http://127.0.0.1/api/mobile/v1/'),fixture:true,client:MockClient((request)async{if(request.url.path.endsWith('/retired-authority')){retirements++;expect(jsonDecode(request.body),{'originalSessionId':fixture.session('1')['sessionId']});return http.Response(jsonEncode({'kind':'BENEFICIARY_AUTHORITY_RETIRED','accountId':replacement['accountId'],'originalSessionId':fixture.session('1')['sessionId'],'deviceId':id(99)}),200);}verifies++;return http.Response(jsonEncode(receipt()),200);}));addTearDown(recovered.close);await recovered.restore();expect(await recovered.pendingSettlementBeneficiary(),isNull);expect(recovered.signedIn,isTrue);expect(verifies,1);expect(retirements,1);await recovered.submitSettlementBeneficiary(command(96));expect(recovered.signedIn,isTrue);
  });
 test('live authority and mismatched retirement proof preserve journal and replacement login',()async{
  final storage=const FlutterSecureStorage(),mut=VerifySettlementBeneficiary(id(90),SettlementBeneficiaryVerifyCommand(idempotencyKey:id(95),expectedVersion:'1',signature:'1'*88));
  final original=MobileApi(base:Uri.parse('http://127.0.0.1/api/mobile/v1/'),fixture:true,client:MockClient((_)async=>throw http.ClientException('Synthetic unknown verification')));await original.restore();await expectLater(original.submitSettlementBeneficiary(mut),throwsA(isA<http.ClientException>()));original.close();
  final journalKey='bitpos.pendingSettlementBeneficiary.${fixture.session('1')['accountId']}',before=await storage.read(key:journalKey),replacement={...fixture.session('1'),'sessionId':id(97)};await storage.write(key:'bitpos.mobileSession',value:jsonEncode(replacement));var attempts=0;
  final recovered=MobileApi(base:Uri.parse('http://127.0.0.1/api/mobile/v1/'),fixture:true,client:MockClient((request)async{expect(request.url.path.endsWith('/retired-authority'),isTrue);attempts++;if(attempts==1)return http.Response('{"error":{"code":"BENEFICIARY_AUTHORITY_STILL_LIVE"}}',409);return http.Response(jsonEncode({'kind':'BENEFICIARY_AUTHORITY_RETIRED','accountId':replacement['accountId'],'originalSessionId':fixture.session('1')['sessionId'],'deviceId':id(98)}),200);}));addTearDown(recovered.close);await recovered.restore();
  await expectLater(recovered.pendingSettlementBeneficiary(),throwsA(isA<MobileApiException>().having((e)=>e.code,'code','BENEFICIARY_AUTHORITY_STILL_LIVE')));expect(await storage.read(key:journalKey),before);expect(recovered.signedIn,isTrue);
  await expectLater(recovered.pendingSettlementBeneficiary(),throwsA(isA<FormatException>()));expect(await storage.read(key:journalKey),before);expect(recovered.signedIn,isTrue);
 });
}
